+
+#[test]
+fn mapped_read_results_compact_indivisible_source_capacity_without_losing_errors() {
+    for count in [1, 3, 64, 257] {
+        let fs = FsClient::new(ReadOutcomes::default());
+        let file = fs.open("/file").unwrap();
+        let requests: Vec<_> = (0..count).map(|_| file.read_request_at(0, 1)).collect();
+        let outcomes = fs.vread_native(&requests).unwrap();
+        let source_bytes = count * std::mem::size_of::<vfsi_sync::OpResult<ReadResult>>();
+        let slot =
+            std::mem::size_of::<vfsi_sync::OpResult<vfsi_core::api::internal::OwnedReadResult>>();
+        if source_bytes % slot != 0 {
+            assert_eq!(
+                outcomes.capacity(),
+                count,
+                "native capacity must not leak into compact results"
+            );
+        }
+        assert_eq!(outcomes.len(), count);
+        for (index, outcome) in outcomes.into_iter().enumerate() {
+            if index == 1 {
+                let error = outcome.unwrap_err();
+                assert_eq!(error.state(), vfsi_sync::FailureState::Unknown);
+                assert_eq!(
+                    vfsi_core::transport_kind(error.cause()),
+                    Some(vfsi_core::TransportKind::Other)
+                );
+                assert_eq!(
+                    vfsi_core::internal::errors::path(error.cause()),
+                    Some(std::path::Path::new("/file"))
+                );
+                let Some(vfsi_sync::IoProgress::Read(prefix)) = error.progress() else {
+                    panic!("confirmed prefix lost")
+                };
+                assert_eq!(prefix.data(), Some(b"p".as_slice()));
+            } else {
+                assert_eq!(outcome.unwrap().data, b"x");
+            }
+        }
+        file.close().unwrap();
+        let backend = fs.into_inner().unwrap();
+        assert_eq!(backend.calls, 1);
+        assert_eq!(backend.lengths, [count]);
+    }
+}
